(()=>{'use strict';if(!localStorage.getItem('nova-session')&&sessionStorage.getItem('nova-session'))localStorage.setItem('nova-session',sessionStorage.getItem('nova-session'));const $=s=>document.querySelector(s),base='https://api.novaclient.tech/license/account';let csrf='',titleFrame=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches;const labels={playtime:'Time played',tries:'Map attempts',saves:'Saves',freezes:'Freezes',lasts:'Lasts',deaths:'Deaths'};const show=(id,on=true)=>$(id).hidden=!on;const number=n=>new Intl.NumberFormat('en').format(n);const format=(v,m)=>m==='playtime'?`${number(Math.floor(v/3600))}h ${Math.floor(v%3600/60)}m`:number(v);function message(t){$('#message').textContent=t||''}async function api(path,form){const r=await fetch(base+path,{credentials:'omit',headers:{...(localStorage.getItem('nova-session')?{Authorization:'Bearer '+localStorage.getItem('nova-session')}:{})},...(form?{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded',...(localStorage.getItem('nova-session')?{Authorization:'Bearer '+localStorage.getItem('nova-session')}:{})},body:new URLSearchParams({...form,csrf})}:{})});const d=await r.json();if(!r.ok)throw Object.assign(new Error(d.error||'Could not load this page. Try again.'),{status:r.status});return d}function text(tag,value,cls){const e=document.createElement(tag);e.textContent=value;if(cls)e.className=cls;return e}
function animateTitle(title){cancelAnimationFrame(titleFrame);const root=$('#title');root.replaceChildren();show('#title',!!title);if(!title)return;root.setAttribute('aria-label',title.name);const chars=Array.from(title.name),spans=chars.map(c=>{const span=text('span',c===' '?'\u00a0':c);span.setAttribute('aria-hidden','true');root.append(span);return span});const a=[title.color1>>16&255,title.color1>>8&255,title.color1&255],b=[title.color2>>16&255,title.color2>>8&255,title.color2&255],start=performance.now();function frame(now){const phase=paused?0:(now-start)/1000*title.speed/100;spans.forEach((span,i)=>{const pos=i/Math.max(1,chars.length-1),mix=paused?pos:.5+.5*Math.sin(pos*Math.PI+phase*1.8);span.style.color=title.mode==='rgb'?`hsl(${((i/12+phase*.22)%1)*360} 100% 60%)`:`rgb(${a.map((x,j)=>title.mode==='solid'?x:x+(b[j]-x)*mix).join(' ')})`;span.style.opacity=(!paused&&title.animation==='pulse')?String(.75+.25*Math.sin(phase*3)):'1';span.style.transform=(!paused&&title.animation==='wave')?`translateY(${Math.sin(phase*3-i*.5)*parseFloat(getComputedStyle(root).fontSize)*.09}px)`:'none'});if(!document.hidden&&!paused)titleFrame=requestAnimationFrame(frame)}frame(start);const toggle=text('button',paused?'Play title animation':'Pause title animation','quiet');toggle.type='button';toggle.addEventListener('click',()=>{paused=!paused;animateTitle(title)});root.append(document.createTextNode(' '),toggle)}
async function load(){message('');for(const id of ['#login','#verify','#link','#profile'])show(id,false);try{const state=await api('/state');csrf=state.csrf;document.dispatchEvent(new CustomEvent('nova-account-state',{detail:state}));show('#logout');if(state.profile&&!state.verified){show('#intro',false);show('#profile');const p=state.profile;$('#player-name').textContent=p.name;$('#role').textContent=p.role;animateTitle(p.title);$('#stats').replaceChildren();for(const metric of ['playtime','tries','saves','freezes','lasts','deaths']){const stat=text('a','','stat');stat.href='/account/leaderboards/?metric='+metric;stat.setAttribute('aria-label','View '+labels[metric]+' leaderboard');stat.append(text('span',labels[metric]),text('strong',p.stats?format(p.stats[metric],metric):'—'));$('#stats').append(stat)}$('#updated').textContent=p.stats?'Last synced '+new Date(p.stats.updated_at*1000).toLocaleString('en'):'No stats synced yet. Play with the latest NovaClient to start recording.';$('#maps').replaceChildren();p.maps.forEach((m,i)=>{const li=text('li','','map-row');li.append(text('span',String(i+1).padStart(2,'0')),text('strong',m.map),text('em',number(m.tries)+' tries'));$('#maps').append(li)});if(!p.maps.length)$('#maps').append(text('li','No map attempts synced yet.','hint'))}else{show('#intro');show(state.verified?'#link':'#verify')}}catch(e){if(e.status===401){show('#intro');show('#login');show('#logout',false)}else message(e.message)}}
for(const [id,path]of [['#verify-form','/verify'],['#link-form','/link']])$(id).addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;message('');try{await api(path,Object.fromEntries(new FormData(e.target)));e.target.reset();await load()}catch(error){message(error.message)}finally{button.disabled=false}});$('#reverify').onclick=()=>{show('#profile',false);show('#verify');$('#code').focus()};async function ranking(){message('');const list=$('#ranking-list');list.replaceChildren(text('li','Loading rankings…','hint'));try{const d=await api('/ranking?metric='+encodeURIComponent($('#metric').value));list.replaceChildren();d.players.forEach((p,i)=>{const li=text('li','','rank-row');li.append(text('span',String(i+1).padStart(2,'0'),'rank'),text('strong',p.name),text('em',format(p.value,d.metric)));list.append(li)});show('#ranking-empty',!d.players.length)}catch(e){list.replaceChildren();message(e.message)}}const initialMetric=new URLSearchParams(location.search).get('metric');if(Object.hasOwn(labels,initialMetric))$('#metric').value=initialMetric;$('#metric').onchange=ranking;const rankings=location.pathname.replace(/\/$/,'').endsWith('/leaderboards');for(const a of document.querySelectorAll('[data-tab]'))if(a.dataset.tab===(rankings?'rankings':'profile'))a.setAttribute('aria-current','page');async function boot(){const code=new URLSearchParams(location.hash.slice(1)).get('login');if(code){history.replaceState(null,'',location.pathname+location.search);try{const result=await api('/exchange',{code});localStorage.setItem('nova-session',result.token)}catch(e){show('#login');message(e.message);return}}if(rankings){show('#intro',false);show('#rankings');ranking()}else load()}boot();document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!rankings)load()})})();
